          if (leg.lender !== r) leg.lender.usedOwn += leg.amount;
          member.borrowedInFlight += leg.amount;
          borrowPart += leg.amount;
        }
      }
      occupations.push({ member, units: occ.units, ownPart, borrowPart, gen: member.ownGen });
    }
    return occupations;
  }

  // One release closure drops every member occupation of a combo handle.
  function makeComboHandle(occupations) {
    const records = [];
    const releaseOne = (occ) => (record) => {
      occ.member.openHandles.delete(record);
      if (occ.gen !== occ.member.ownGen) return; // member window closed; cleared
      occ.member.inFlight -= occ.units;
      occ.member.borrowedInFlight -= occ.borrowPart;
      for (const leg of occ.legs) {
        if (!leg.active) continue;
