function migrateLegsOf(node, oldRootState, newRootState, moved) {
  for (const leg of node.activeBorrowerLegs) {
    if (leg.pGen === oldRootState.poolGen) leg.pGen = newRootState.poolGen;
    if (!moved.has(leg.lender)) {
