  // ...then the admitted lend: d keeps its 2 own units, loses the 2 lent.
  assert.equal(d.stats().inFlight, 2);
  hOccupation.release(); // the handle stays valid; releases the own part
  assert.equal(d.stats().inFlight, 0);

