// Occupations are never torn apart. A queued combo is unfit as soon as one
// of its members can never cover its share of its own limit.
function entryUnfittable(entry, newLimit) {
  if (!entry.isCombo) return entry.units > newLimit;
  for (const occ of entry.occs) {
    if (occ.units > occ.member.limit) return true;
  }
  return false;
}

function refuseUnfittable(ownerFilter, newLimit) {
  const r = state.root;
  const q = r.queue;
  let touched = false;
  for (let i = r.head; i < q.length; i += 1) {
    const entry = q[i];
    if (entry.removed) continue;
    if (entry.isCombo) {
      if (entryUnfittable(entry) && entry.occs.some((occ) => ownerFilter(occ.member))) {
        settleEntry(entry, 'refused');
        touched = true;
      }
    } else if (entry.units > newLimit && ownerFilter(entry.owner)) {
      settleEntry(entry, 'refused');
      touched = true;
    }
  }
  if (touched) recomputeMinDeadline();
}

